from abc import abstractproperty
import re
import paramiko
from time import sleep
from paramiko import SSHException
from taf.hw.rf_switch.devices.rf_switch import RfSwitch
from taf.hw.rf_switch.exceptions import RfSwitchActionFailed


class BaseOrbis(RfSwitch):
    RST_COMMAND = "*RST"
    IDN_COMMAND = '"*IDN?" 1024'
    OPEN_COMMAND = '"ROUT:OPEN:ALL"'
    STAT_COMMAND = '"ROUT:CLOS:STAT?" 1024'
    CLS_COMMAND = '"ROUT:CLOS (@{port_in}{port_out}00)"'
    OPEN_ONE_COMMAND = '"ROUT:OPEN (@{connection})"'

    @abstractproperty
    def SUPPORTED_PORT_IN_VALUES(self):
        """ List[str] """
        pass

    @abstractproperty
    def SUPPORTED_PORT_OUT_VALUES(self):
        """ List[str] """
        pass

    @abstractproperty
    def DEVICE_TYPE(self):
        """ str """
        pass

    def __init__(self, ip, port=22):
        """
        Initial ssh connection
        self.config_user for login user
        self.config_password for login password
        """
        super().__init__()
        self.ip = ip
        self.port = int(port)
        self.config_user = 'root'
        self.config_password = 'arm'
        self.ssh_client = paramiko.SSHClient()
        self.ssh_client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        try:
            self.ssh_client.connect(hostname=self.ip, port=self.port,
                                    username=self.config_user, password=self.config_password,
                                    timeout=10, allow_agent=False)
        except SSHException:
            raise RfSwitchActionFailed(f"Orbis SSH login {self.ip}:{self.port} fail")
        self._verify_device_status()

    def connect_ports(self, port_in, port_out):
        """
        For port_in=2 and port_out=1:

        Checks previous connect commands, that were using given port_out:

            /usr/bin/orbis/Vxi11Client 127.0.0.1 "ROUT:CLOS:STAT?" 1024

        Disconnects all found connections*, for example

            /usr/bin/orbis/Vxi11Client 127.0.0.1 "ROUT:OPEN (@1100)"
            /usr/bin/orbis/Vxi11Client 127.0.0.1 "ROUT:OPEN (@3100)"

        Connects given port_in with port_out

            /usr/bin/orbis/Vxi11Client 127.0.0.1 "ROUT:CLOS (@2100)"

        *There is no way of knowing which ports are currently connected.
        It's been reported, that connecting port_out to some port_in,
        while this port_out is already connected to another port_in,
        may cause failures.
        Therefore we need to disconnect any previous connections,
        even if they are already disconnected.
        """
        self._verify_ports_in_range(port_in, port_out)
        previous_connections = self._get_connection_history(port_out)
        self._disconnect_connections(previous_connections)
        self._connect_ports(port_in, port_out)

    def _verify_device_status(self):
        response = self._execute_vxi11client(self.IDN_COMMAND)
        if self.DEVICE_TYPE not in response:
            msg = 'Expected model: Orbis {} not found in device response'
            raise RfSwitchActionFailed(msg.format(self.DEVICE_TYPE))

    def _verify_ports_in_range(self, port_in, port_out):
        if str(port_in) not in self.SUPPORTED_PORT_IN_VALUES:
            raise RfSwitchActionFailed(f'Given port_in: {port_in} is not supported.')
        if str(port_out) not in self.SUPPORTED_PORT_OUT_VALUES:
            raise RfSwitchActionFailed(f'Given port_out: {port_out} is not supported.')

    def _get_connection_history(self, port_out):
        """
        Returns a list of previously connected ports,
        that involved given port_out.

        # Vxi11Client  127.0.0.1 "ROUT:CLOS:STAT?" 1024

        response example:
            device_write_1
            start device_intr_srq_1_svc
            Service request received from  STB = 49
            stop device_intr_srq_1_svc
            device_read_1
            device_read_2
            device_read_3
            print result
            (@1200,2100,13100)
        If port_out=1 then this method returns: ['2100', '13100']
        """
        connection_history = []
        response = self._execute_vxi11client(self.STAT_COMMAND)
        previous_port_out_connections = str(re.search('\\(@(.*)\\)', response).group(1)).split(",")
        for connection in previous_port_out_connections:
            if len(connection) >= 3 and connection[-3] == port_out:
                connection_history.append(connection)
        return connection_history

    def _disconnect_connections(self, connections):
        for connection in connections:
            cmd = self.OPEN_ONE_COMMAND.format(connection=connection)
            recv = self._execute_vxi11client(cmd)
            if "device_write_1" not in recv:
                raise RfSwitchActionFailed(f'Open switch route number {connection} error.')
            sleep(2)

    def _connect_ports(self, port_in, port_out):
        route_sid = self.CLS_COMMAND.format(port_in=port_in, port_out=port_out)
        recv = self._execute_vxi11client(route_sid)
        if not recv:
            raise RfSwitchActionFailed(f'Close switch route number {port_in} error.')

    def _execute_vxi11client(self, command):
        vxi11client_path = "/usr/bin/orbis/Vxi11Client"
        server_host = "127.0.0.1"
        vxi11client_command = " ".join([vxi11client_path, server_host, command]).encode()
        stdin, stdout, stderr = self.ssh_client.exec_command(vxi11client_command)
        result = stdout.read().decode('utf-8')
        if len(result) == 0:
            raise RfSwitchActionFailed("Received empty response from the device.")
        return result

    def disconnect_ports(self, port_in, port_out='1'):
        raise NotImplementedError

    def get_port_in_status(self, port_in="1"):
        """
        Can't implement because the functionality described in device manual works incorrectly
        """
        raise NotImplementedError("The functionality described in device manual works incorrectly")

    def get_port_out_status(self, port_out="1"):
        """
        Can't implement because the functionality described in device manual works incorrectly
        """
        raise NotImplementedError("The functionality described in device manual works incorrectly")

    def get_connected_ports(self):
        """
        Can't implement because the functionality described in device manual works incorrectly
        """
        raise NotImplementedError("The functionality described in device manual works incorrectly")


class ORBIS24x4(BaseOrbis):
    """
    Module to control Orbis types based RF switches.
    """
    SUPPORTED_PORT_IN_VALUES = [str(value) for value in range(1, 25)]
    SUPPORTED_PORT_OUT_VALUES = [str(value) for value in range(1, 5)]
    DEVICE_TYPE = '24x4'


class ORBIS64x4(BaseOrbis):
    """
    Module to control Orbis types based RF switches.

    This is an Orbis Barrel:
     _________
    |         |
    | 8  1  2 |     Orbis64 has 64 ports (8 barrels, each with 8 ports)
    | 7     3 |     Connecting to port 23 would mean opening all ports
    | 6  5  4 |     and then closing the 7th port on 3rd barrel.
    |_________|
    """
    SUPPORTED_PORT_IN_VALUES = [str(value) for value in range(1, 65)]
    SUPPORTED_PORT_OUT_VALUES = "1"
    DEVICE_TYPE = '64x4'

    ROUTES_PER_BARREL = 8
    BARRELS_HAVE_EVEN_INDEX = 2

    def connect_ports(self, port_in, port_out="1"):
        """
        port_in: str
        port_out: useless   (it is not used, but it is required by facade)

        Seems that ROUT:CLOS(@SW<port_in><port_out>00) command did not get through to the device.
        You can try to figure out what, but we have spend several manhours, without success.

        Functionality described in device manual works incorrectly.
        Functionality implemented in the base class works incorrectly (at least for Orbis64x4).
        """
        self._verify_ports_in_range(port_in, port_out)

        port_in = int(port_in)
        self.open_all_routes()

        barrel_index = self._get_barrel_index_from_port(port_in)
        for lower_barrel_index in self._get_lower_index_barrels(barrel_index):
            self._execute_vxi11client(f'"ROUT:CLOS(@SW{lower_barrel_index}_NO)"')

        self._execute_vxi11client(f'"ROUT:CLOS(@SW{self._get_routes_index_from_barrel_index(barrel_index)}_{self._get_absolute_route_index_from_port(port_in)})"')

    def open_all_routes(self):
        self._execute_vxi11client('":ROUT:OPEN:ALL"')

    def _get_absolute_route_index_from_port(self, port):
        """ port: int, Returns: int [1-8] """
        return self.ROUTES_PER_BARREL if (port % self.ROUTES_PER_BARREL) == 0 else (port % self.ROUTES_PER_BARREL)

    def _get_barrel_index_from_port(self, port):
        return ((port // self.ROUTES_PER_BARREL) + 1) * self.BARRELS_HAVE_EVEN_INDEX

    def _get_routes_index_from_barrel_index(self, barrel_index):
        return barrel_index - 1

    def _get_lower_index_barrels(self, barrel_index):
        return [index for index in range(2, barrel_index) if index % 2 == 0]

    def _input_port_in_allowed_range(self, port):
        if 1 <= port and port <= 64:
            return True
        return False


class ORBIS6x6(BaseOrbis):
    """
    Module to control Orbis types based RF switches.
    """
    SUPPORTED_PORT_IN_VALUES = [str(value) for value in range(1, 7)]
    SUPPORTED_PORT_OUT_VALUES = [str(value) for value in range(1, 7)]
    DEVICE_TYPE = '6x6'
